    }).replace(/<li\b[^>]*>/gi, "\n- ").replace(/<\/tr>/gi, "\n").replace(/<(td|th)\b[^>]*>/gi, " | ").replace(/<br\s*\/?>/gi, "\n").replace(/<\/(p|div|section|article|blockquote|ul|ol|table|dl|dt|dd)>/gi, "\n\n").replace(/<[^>]+>/g, " ");
    let decoded = decodeHtmlEntities(working).replace(/[ \t]+\|/g, " |").replace(/\|[ \t]+/g, "| ").replace(/[ \t]{2,}/g, " ");
    decoded = cleanTextPreserveLines(decoded);
    for (let i = 0; i < preservedBlocks.length; i++) {
      decoded = decoded.replace(`__NLS_PRESERVED_BLOCK_${i}__`, () => preservedBlocks[i]);
    }
    return {
      text: decoded.replace(/\n{3,}/g, "\n\n").trim().slice(0, maxChars),
      publishedDate,
      extractedTitle,
      extractedLinks
    };
  }

  function repairTruncatedJson(rawText) {
    if (!rawText) return null;
    let s = String(rawText).trim();
    if (s.startsWith("```")) {
      s = s.replace(/^```(?:json)?\s*\n?/i, "").replace(/\n?```\s*$/i, "").trim();
    }
    const firstStart = s.search(/[\[{]/);
    if (firstStart < 0) return null;
    if (firstStart > 0) s = s.slice(firstStart);
    let out = "";
    const stack = [];
    let inString = false;
    let escaped = false;
    let started = false;
    for (let i = 0; i < s.length; i++) {
      const ch = s[i];
      if (inString) {
        if (ch === "\n") {
          out += "\\n";
          escaped = false;
          continue;
        }
        if (ch === "\r") {
          out += "\\r";
          escaped = false;
          continue;
        }
        out += ch;
        if (escaped) {
          escaped = false;
        } else if (ch === "\\") {
          escaped = true;
        } else if (ch === '"') {
          inString = false;
        }
        continue;
      }
      if (ch === '"') {
        inString = true;
        out += ch;
      } else if (ch === "{") {
        started = true;
        stack.push("}");
        out += ch;
      } else if (ch === "[") {
        started = true;
        stack.push("]");
        out += ch;
      } else if (ch === "}" || ch === "]") {
        out = out.replace(/,\s*$/, "");
        if (stack.length > 0 && stack[stack.length - 1] === ch) {
          stack.pop();
          out += ch;
          if (started && stack.length === 0) break;
        }
      } else {
        out += ch;
      }
    }
    if (inString) {
      if (escaped) {
        out = out.slice(0, -1);
      } else {
        out = out.replace(/\\u[0-9a-fA-F]{0,3}$/, "");
      }
      out += '"';
    }
    out = out.replace(/,\s*$/, "");
    if (stack.length > 0 && stack[stack.length - 1] === "}") {
      const danglingKeyMatch = out.match(/([,{]\s*)"[^"]*"\s*$/);
      if (danglingKeyMatch) {
        out = out.slice(0, out.length - danglingKeyMatch[0].length + danglingKeyMatch[1].length).replace(/,\s*$/, "");
      }
    }
    out = out.replace(/(:\s*)(?:t|tr|tru|f|fa|fal|fals|n|nu|nul|-|\d+\.|\d+[eE][+-]?)$/, "$1null");
    out = out.replace(/(,\s*)(?:t|tr|tru|f|fa|fal|fals|n|nu|nul|-|\d+\.|\d+[eE][+-]?)$/, "");
    if (/:\s*$/.test(out)) out += "null";
    out = out.replace(/,\s*$/, "");
    while (stack.length > 0) {
      out += stack.pop();
    }
    return out;
  }

  function parseStructuredJson(rawText) {
    if (!rawText || typeof rawText !== "string") return { parsed: null, repaired: false, error: "empty_response" };
    const trimmed = rawText.trim();
    try {
      return { parsed: JSON.parse(trimmed), repaired: false, error: null };
    } catch (directErr) {
      try {
        const candidate = repairTruncatedJson(trimmed);
        if (!candidate) return { parsed: null, repaired: false, error: directErr.message };
        const parsed = JSON.parse(candidate);
        diagnostics.json_repairs += 1;
        return { parsed, repaired: true, error: null };
      } catch (repairErr) {
        return { parsed: null, repaired: false, error: directErr.message };
      }
    }
  }

  async function loadSheetJS() {
    const target = typeof globalThis !== "undefined" ? globalThis : this;
    if (target && target.XLSX) return target.XLSX;
    if (sheetJsPromise) return sheetJsPromise;
    sheetJsPromise = (async () => {
      const xlsxUrl = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
      try {
        const res = await fetchWithTimeout(xlsxUrl, {}, 12e3);
        if (!res.ok) return null;
        const code = await res.text();
        const mod = { exports: {} };
        const fn = new Function("module", "exports", "window", "global", "globalThis", code);
        fn(mod, mod.exports, target, target, target);
        return (mod.exports && mod.exports.read ? mod.exports : null) || target.XLSX || null;
      } catch (e) {
        diagnostics.hydration_failures.push(`sheetjs_load_failed: ${e.message || "unknown"}`);
        return null;
      } finally {
        if (!(target && target.XLSX)) sheetJsPromise = null;
      }
    })();
    return sheetJsPromise;
  }

  async function extractTextFromExcelData(arrayBuffer) {
    try {
      const xlsx = await loadSheetJS();
      if (!xlsx) return { ok: false, text: "", sheets: [] };
      const workbook = xlsx.read(arrayBuffer, { type: "array" });
      let fullText = "";
      const sheets = [];
      const sheetNames = workbook.SheetNames.slice(0, 6);
      for (const sheetName of sheetNames) {
        const sheet = workbook.Sheets[sheetName];
        const csv = xlsx.utils.sheet_to_csv(sheet);
        if (csv && csv.trim().length > 0) {
          sheets.push({ name: sheetName, csv });
          fullText += `[Spreadsheet Tab: ${sheetName}]\n${csv.slice(0, 3e4)}\n\n`;
        }
      }
      return { ok: fullText.trim().length > 10, text: cleanTextPreserveLines(fullText), sheets };
    } catch (err) {
      diagnostics.hydration_failures.push(`excel_parse_failed: ${err.message || "unknown"}`);
      return { ok: false, text: "", sheets: [] };
    }
  }

  const OFFICE_MIME_MAP = {
    ".xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
  };

  function supportsNativeOfficeBlocks(modelId) {
    return /^gemini-4-/i.test(modelId);
  }

  async function readResponseBufferWithLimit(res, maxBytes) {
    if (res.body && typeof res.body.getReader === "function") {
      const reader = res.body.getReader();
      const chunks = [];
      let total = 0;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          if (!value) continue;
          total += value.byteLength;
          if (total > maxBytes) {
            try {
              await reader.cancel();
            } catch (e) {
            }
            return { exceeded: true, buffer: null, byteLength: total };
          }
          chunks.push(value);
        }
      } finally {
        try {
          reader.releaseLock();
        } catch (e) {
        }
      }
      const merged = Buffer.concat(chunks.map((c) => Buffer.from(c.buffer, c.byteOffset, c.byteLength)), total);
      return { exceeded: false, buffer: merged, byteLength: total };
    }
    const ab = await res.arrayBuffer();
    if (ab.byteLength > maxBytes) {
      return { exceeded: true, buffer: null, byteLength: ab.byteLength };
    }
    return { exceeded: false, buffer: Buffer.from(ab), byteLength: ab.byteLength };
  }

  async function fetchAndHydrateDocument(url, options = {}) {
    const {
      maxPdfBytes = 14 * 1024 * 1024,
      maxTextBytes = 8 * 1024 * 1024,
      enforcePublicUrl = false
    } = options;
    const failResult = { success: false, type: "unknown", is_native_pdf: false, text: "", publishedDate: null, extractedLinks: [], sheets: [] };
    if (enforcePublicUrl && !isSafePublicHttpUrl(url)) {
      diagnostics.hydration_failures.push(`blocked_non_public_url: ${truncate(url, 120)}`);
      return failResult;
    }
    try {
      const res = await fetchWithTimeout(url, {
        headers: {
          "User-Agent": "Mozilla/5.0 (compatible; GeminiGroundedSearch/4.0; +https://ai.google.dev)",
          "Accept": "application/pdf,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel,text/csv,text/html,application/xhtml+xml,text/plain,*/*"
        }
      }, 18e3);
      if (!res.ok) {
        diagnostics.hydration_failures.push(`http_${res.status}: ${safeDomain(url)}`);
        return failResult;
      }
      const contentType = (res.headers.get("content-type") || "").toLowerCase();
      const lastModifiedHeader = res.headers.get("last-modified");
      const pathnameLower = safePathname(url).toLowerCase();
      const isPdfByHeaderOrExt = contentType.includes("application/pdf") || pathnameLower.endsWith(".pdf");
      const isCsv = contentType.includes("text/csv") || pathnameLower.endsWith(".csv");
      const isExcel = contentType.includes("spreadsheet") || contentType.includes("ms-excel") || pathnameLower.endsWith(".xlsx") || pathnameLower.endsWith(".xls");
      const maxAllowedBytes = isPdfByHeaderOrExt || isExcel ? maxPdfBytes : maxTextBytes;
      const contentLength = Number(res.headers.get("content-length") || 0);
      if (contentLength > maxAllowedBytes) {
        diagnostics.hydration_failures.push(`payload_too_large (${Math.round(contentLength / 1024)}KB): ${safeDomain(url)}`);
        return failResult;
      }
      const readRes = await readResponseBufferWithLimit(res, maxAllowedBytes);
      if (readRes.exceeded || !readRes.buffer || readRes.byteLength < 16) {
        if (readRes.exceeded) diagnostics.hydration_failures.push(`stream_exceeded_limit: ${safeDomain(url)}`);
        return failResult;
      }
      const buf = readRes.buffer;
      const magic = buf.subarray(0, 5).toString("latin1");
      if (magic.startsWith("%PDF")) {
        if (buf.byteLength < 64) return failResult;
        const pdfBase64 = buf.toString("base64");
        return {
          success: true,
          type: "pdf",
          is_native_pdf: true,
          pdf_base64: pdfBase64,
          pdf_byte_length: buf.byteLength,
          mime_type: "application/pdf",
          text: `[NATIVE MULTIMODAL PDF DOCUMENT (${Math.round(buf.byteLength / 1024)} KB) \u2014 Evaluated directly via Gemini native vision/document understanding without lossy text flattening. URL: ${url}]`,
          publishedDate: null,
          lastModified: normalizeIsoDate(lastModifiedHeader),
          extractedLinks: [],
          sheets: []
        };
      }
      if (isExcel) {
        const ab = buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
        const parsedExcel = await extractTextFromExcelData(ab);
        if (parsedExcel.ok) {
          return {
            success: true,
            type: "excel",
            is_native_pdf: false,
            text: parsedExcel.text,
            sheets: parsedExcel.sheets,
            publishedDate: null,
            lastModified: normalizeIsoDate(lastModifiedHeader),
            extractedLinks: []
          };
        }
        if (supportsNativeOfficeBlocks(generativeModel) && pathnameLower.endsWith(".xlsx")) {
          return {
            success: true,
            type: "office_document",
            is_native_pdf: true,
            pdf_base64: buf.toString("base64"),
            pdf_byte_length: buf.byteLength,
            mime_type: OFFICE_MIME_MAP[".xlsx"],
            text: `[NATIVE MULTIMODAL SPREADSHEET (${Math.round(buf.byteLength / 1024)} KB) \u2014 URL: ${url}]`,
            publishedDate: null,
            lastModified: normalizeIsoDate(lastModifiedHeader),
            extractedLinks: [],
            sheets: []
          };
        }
        if (buf.subarray(0, 2).toString("latin1") === "PK") {
          return failResult;
        }
      }
      const decodedText = new TextDecoder("utf-8", { fatal: false }).decode(buf);
      if (isCsv && !/<html\b|<!doctype\s+html/i.test(decodedText.slice(0, 500))) {
        const cleaned = cleanTextPreserveLines(decodedText).slice(0, 11e4);
        return {
          success: cleaned.length > 20,
          type: "csv",
          is_native_pdf: false,
          text: cleaned,
          sheets: [{ name: "data", csv: decodedText }],
          publishedDate: null,
          lastModified: normalizeIsoDate(lastModifiedHeader),
          extractedLinks: []
        };
      }
      if (contentType.includes("text/plain") || contentType.includes("text/markdown") || contentType.includes("application/json")) {
        const cleaned = cleanTextPreserveLines(decodedText).slice(0, 11e4);
        return {
          success: cleaned.length > 30,
          type: "text",
          is_native_pdf: false,
          text: cleaned,
          publishedDate: null,
          lastModified: normalizeIsoDate(lastModifiedHeader),
          extractedLinks: [],
          sheets: []
        };
      }
      const parsedHtml = extractStructuredHtml(decodedText, 11e4);
      if (parsedHtml.text.length > 80) {
        return {
          success: true,
          type: "html",
          is_native_pdf: false,
          text: parsedHtml.text,
          extractedTitle: parsedHtml.extractedTitle,
          publishedDate: parsedHtml.publishedDate,
          lastModified: normalizeIsoDate(lastModifiedHeader),
          extractedLinks: parsedHtml.extractedLinks || [],
          sheets: []
        };
      }
    } catch (e) {
      diagnostics.hydration_failures.push(`${safeDomain(url)}: ${e.message || "fetch_failed"}`);
    }
    return failResult;
  }

  const wsRef = typeof workspace !== "undefined" && workspace || resources && resources.workspace || null;

  async function stageDocumentToWorkspace(url, hydrated, isExplicit) {
    const stagedPaths = [];
    if (!wsRef || typeof wsRef.writeFile !== "function" || !hydrated || hydrated.is_native_pdf) {
      return stagedPaths;
    }
    const isTabular = hydrated.type === "csv" || hydrated.type === "excel";
    const isLargeText = Boolean(hydrated.text && hydrated.text.length >= 12e3 && detailMode !== "MINIMAL");
    const shouldStageIn = isTabular || isLargeText || (isExplicit && (detailMode === "EXHAUSTIVE" || detailMode === "RAW_TEXT"));
    if (!shouldStageIn) return stagedPaths;
    const domSlug = safeDomain(url).replace(/[^a-z0-9.-]/g, "_").slice(0, 40);
    const idHash = shortHash(url);
    try {
      if (hydrated.type === "excel" && Array.isArray(hydrated.sheets) && hydrated.sheets.length > 0) {
        for (let i = 0; i < hydrated.sheets.length; i++) {
          const sh = hydrated.sheets[i];
          const sheetSlug = String(sh.name || `sheet${i + 1}`).replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 24);
          const fname = `hydrated_${domSlug}_${idHash}_${sheetSlug}.csv`;
          const res = await wsRef.writeFile(fname, sh.csv, "in");
          stagedPaths.push(res?.relativePath || `in/${fname}`);
        }
      } else if (hydrated.type === "csv" && hydrated.sheets?.[0]?.csv) {
        const fname = `hydrated_${domSlug}_${idHash}.csv`;
        const res = await wsRef.writeFile(fname, hydrated.sheets[0].csv, "in");
        stagedPaths.push(res?.relativePath || `in/${fname}`);
      } else if (hydrated.text) {
        const fname = `nls_${domSlug}_${idHash}.md`;
        const header = `# Source: ${hydrated.extractedTitle || safeDomain(url)}\nURL: ${url}\nPublishedDate: ${hydrated.publishedDate || hydrated.lastModified || "UNKNOWN"}\n\n`;
        const res = await wsRef.writeFile(fname, header + hydrated.text, "in");
        stagedPaths.push(res?.relativePath || `in/${fname}`);
      }
    } catch (e) {
      diagnostics.hydration_failures.push(`workspace_stage_failed (${safeDomain(url)}): ${e.message || "write_error"}`);
    }
    return stagedPaths;
  }

  function resolveThinkingLevel(modelId, stageDesiredLevel) {
    const m = String(modelId || "").toLowerCase();
    const desired = String(stageDesiredLevel || "medium").toLowerCase();
    if (/omni|image|banana/.test(m) && desired === "medium") {
      return "high";
    }
    if (desired === "xhigh") {
      return /hydrogen|neon/.test(m) ? "xhigh" : "high";
    }
    if (desired === "minimal") {
      return /^gemini-4-/.test(m) ? "low" : "low";
    }
    if (["low", "medium", "high"].includes(desired)) {
      return desired;
    }
    return "medium";
  }

  function extractTextFromInteraction(data, preferLastStepForJson = false) {
    if (!data) return "";
    if (typeof data.output_text === "string" && data.output_text.length > 0) return data.output_text;
    const stepTexts = [];
    if (Array.isArray(data.steps)) {
      for (const step of data.steps) {
        if ((step.type === "model_output" || !step.type) && Array.isArray(step.content)) {
          const stepParts = [];
          for (const block of step.content) {
            if (block && block.type === "text" && typeof block.text === "string") {
              stepParts.push(block.text);
            }
          }
          const joined = stepParts.join("").trim();
          if (joined) stepTexts.push(joined);
        }
      }
    }
    if (stepTexts.length > 0) {
      if (preferLastStepForJson && stepTexts.length > 1) {
        const last = stepTexts[stepTexts.length - 1];
        if (/^\s*[\[{]/.test(last) || /^\s*```(?:json)?/i.test(last)) {
          return last;
        }
      }
      return stepTexts.join("");
    }
    const parts = [];
    if (Array.isArray(data.outputs)) {
      for (const block of data.outputs) {
        if (block && block.type === "text" && typeof block.text === "string") {
          parts.push(block.text);
        }
      }
    }
    return parts.join("");
  }

  function recordUsageTokens(usage) {
    if (!usage || typeof usage !== "object") return;
    const total = Number(usage.total_tokens || usage.totalTokenCount || ((usage.input_tokens || usage.promptTokenCount || 0) + (usage.output_tokens || usage.candidatesTokenCount || 0)) || 0);
    if (Number.isFinite(total) && total > 0) {
      diagnostics.total_tokens += total;
    }
  }

  async function callGemini({
    systemInstruction,
    inputBlocks,
    responseSchema,
    thinkingLevel = "medium",
    maxOutputTokens = 65536,
    timeoutMs = 42e3
  }) {
    if (!geminiApiKey) {
      return { ok: false, text: "", status: "missing_api_key", error: "Missing Google Gemini API key" };
    }
    if (isAborted()) {
      return { ok: false, text: "", status: "aborted", error: "aborted_by_caller" };
    }
    const resolvedThinking = resolveThinkingLevel(generativeModel, thinkingLevel);
    let currentMaxTokens = clamp(maxOutputTokens || 65536, 8192, 65536);

    const buildPayload = (includeThinking = true, continuationToken = null) => {
      const p = {
        model: generativeModel
      };
      p.generation_config = { max_output_tokens: currentMaxTokens };
      if (includeThinking && resolvedThinking) {
        p.generation_config.thinking_level = resolvedThinking;
      }
      if (continuationToken) {
        p.continuation_token = continuationToken;
        return p;
      }
      p.input = inputBlocks;
      if (systemInstruction) p.system_instruction = systemInstruction;
      if (responseSchema) {
        p.response_format = {
          type: "text",
          mime_type: "application/json",
          schema: responseSchema
        };
      }
      return p;
    };

    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey,
      "Api-Revision": "2026-05-20"
    };

    let lastError = "unknown_gemini_error";
    let includeThinking = true;
    let retriedThinking = false;
    let retriedMaxTokens = false;

    for (let attempt = 0; attempt < 3; attempt++) {
      try {
        diagnostics.generative_calls += 1;
        const res = await fetchWithTimeout(geminiDirectUrl, {
          method: "POST",
          headers,
          body: JSON.stringify(buildPayload(includeThinking, null))
        }, timeoutMs);
        const rawBody = await res.text();
        let data = null;
        try {
          data = JSON.parse(rawBody);
        } catch (e) {
        }
        if (!res.ok) {
          const errMsg = data?.error?.message || rawBody.slice(0, 300) || `HTTP ${res.status}`;
          lastError = `HTTP ${res.status}: ${errMsg}`;
          if (res.status === 400 && !retriedThinking && includeThinking && /thinking/i.test(errMsg)) {
            includeThinking = false;
            retriedThinking = true;
            continue;
          }
          if (res.status === 400 && !retriedMaxTokens && currentMaxTokens > 8192 && /max_output_tokens|output token/i.test(errMsg)) {
            currentMaxTokens = 8192;
            retriedMaxTokens = true;
            continue;
          }
          break;
        }
        recordUsageTokens(data?.usage);
        let combinedText = extractTextFromInteraction(data, Boolean(responseSchema));
        let status = data?.status || "completed";
        let contToken = data?.continuation_token || null;
        let contCount = 0;
        let contFailed = false;
        while ((status === "requires_continuation" || status === "REQUIRES_CONTINUATION") && contToken && contCount < 2 && remainingBudgetMs() > 10e3 && !isAborted()) {
          contCount += 1;
          diagnostics.generative_calls += 1;
          const contRes = await fetchWithTimeout(geminiDirectUrl, {
            method: "POST",
            headers,
            body: JSON.stringify(buildPayload(includeThinking, contToken))
          }, 18e3);
          if (!contRes.ok) {
            contFailed = true;
            status = "incomplete";
            break;
          }
          const contData = await contRes.json();
          recordUsageTokens(contData?.usage);
          combinedText += extractTextFromInteraction(contData, false);
          status = contData?.status || "completed";
          contToken = contData?.continuation_token || null;
        }
        if (status === "incomplete" || contFailed) {
          diagnostics.incomplete_generations += 1;
        }
        return {
          ok: combinedText.length > 0 && status !== "failed",
          text: combinedText,
          status,
          error: status === "failed" ? data?.error?.message || "interaction_failed" : null
        };
      } catch (err) {
        lastError = err.message || "fetch_exception";
        break;
      }
    }
    return { ok: false, text: "", status: "failed", error: lastError };
  }

  async function callDecisions(inputBlocks, questionsMap, timeoutMs = 2e4) {
    if (!geminiApiKey || verificationEngine === "off" || verificationEngine === "generative_fallback") {
      return { ok: false, answers: null, error: "decisions_disabled_or_missing_key" };
    }
    if (decisionsCircuitOpen) {
      return { ok: false, answers: null, error: "decisions_circuit_open" };
    }
    if (isAborted()) {
      return { ok: false, answers: null, error: "aborted_by_caller" };
    }
    const qKeys = Object.keys(questionsMap || {});
    if (qKeys.length === 0 || qKeys.length > 1e3) {
      return { ok: false, answers: null, error: "invalid_question_count" };
    }
    diagnostics.decisions_api_calls += 1;
    const headers = {
      "Content-Type": "application/json",
      "x-goog-api-key": geminiApiKey
    };
    const payload = {
      model: "gemini-decision-1",
      input: inputBlocks,
      questions: questionsMap
    };
    let lastErr = "decisions_unreachable";
    let shouldOpenCircuit = false;
    try {
      const res = await fetchWithTimeout(decisionsDirectUrl, {
        method: "POST",
        headers,
        body: JSON.stringify(payload)
      }, timeoutMs);
      const raw = await res.text();
      let data = null;
      try {
        data = JSON.parse(raw);
      } catch (e) {
      }
      if (res.ok && data && data.answers) {
        recordUsageTokens(data.usage);
        diagnostics.decisions_api_status = "healthy";
        return { ok: true, answers: data.answers, error: null };
      }
      const errCode = data?.error?.code || `HTTP_${res.status}`;
      const errMsg = data?.error?.message || raw.slice(0, 250);
      lastErr = `${errCode}: ${errMsg}`;
      if (res.status === 401 || res.status === 403 || res.status === 404 || res.status >= 500) {
        shouldOpenCircuit = true;
      }
    } catch (e) {
      lastErr = e.message || "decisions_network_error";
      shouldOpenCircuit = true;
