    const failureNote = `UCS extraction failed (${ucsRun.error || "unknown_synthesis_error"}). Returning SIFT-audited sources and evidence excerpts directly.`;
    if (actionOnError === "throw_error_to_ui") throw new Error(failureNote);
    const errOut = buildErrorEnvelope({
      completion_state: "degraded",
      transport_state: transportState,
      failed_stage: "ucs_synthesis_failed",
      error_diagnostic: failureNote,
      need_class: routePlan.need_class,
      breadth_mode: routePlan.breadth_mode,
      exactness_mode: routePlan.exactness_mode,
      search_mode: routePlan.search_mode,
      branch_statuses: branchStatuses,
      branch_errors: failedRuns.map((r) => ({ branch: r.branch, engine: r.engine, error: r.error })),
      missing_axes: unique([...branchMissingAxes, "ucs_reconciliation_unavailable"]),
      sources: cleanSourcesForOutput,
      fallback_evidence_excerpts: sampleFallbackExcerptsRoundRobin(evidenceLattice, 12),
      citation_graph_warnings: {
        circular_chains: citationGraph.circular_chains,
        single_primary: citationGraph.single_primary
      },
      hop2_verification: hop2Telemetry
    });
    return await enforceParentOutputCap(errOut, evidenceLattice);
  }

  const finalPayload = ucsRun.payload;
  const allMissingFacets = unique([...branchMissingAxes, ...toArray(finalPayload.missing_facets)]);
  const cleanSourceById = new Map(cleanSourcesForOutput.map((s) => [s.id, s]));
  const paywalledDomainsOut = unique(cleanSourcesForOutput.filter((s) => s.access_status === "paywalled_preview").map((s) => s.domain));

  function attachCitedSources(items) {
    return toArray(items).map((entry) => {
      const rawIds = unique(toArray(entry?.sourceIds));
      const validIds = rawIds.filter((sid) => cleanSourceById.has(sid));
      const invalidIds = rawIds.filter((sid) => !cleanSourceById.has(sid));
      const enriched = {
        ...entry,
        source_handles: validIds.map((sid) => `S${sid}`),
        sourceIds: validIds,
        cited_sources: validIds.map((sid) => {
          const src = cleanSourceById.get(sid);
          return {
            handle: `S${src.id}`,
            id: src.id,
            title: src.title,
            url: src.url,
            domain: src.domain,
            publishedDate: src.publishedDate,
            access_status: src.access_status,
            credibility_label: src.credibility_label,
            sift_weight: src.sift_audit?.overall_epistemic_weight ?? null
          };
        })
      };
      if (invalidIds.length > 0) {
        enriched.invalid_source_ids_dropped = invalidIds;
      }
      return enriched;
    });
  }

  const dataLayerOut = {
    sources: cleanSourcesForOutput,
    artifacts: attachCitedSources(finalPayload.artifacts),
    structured_items: attachCitedSources(finalPayload.structured_items),
    claims: attachCitedSources(finalPayload.claims),
    filtered_unverified_claims: finalPayload.filtered_unverified_claims || [],
    missing_facets: allMissingFacets
  };
  if (detailMode === "RAW_TEXT") {
    dataLayerOut.raw_evidence_windows = evidenceLattice.map((w) => ({
      sourceHandle: `S${w.sourceId}`,
      sourceId: w.sourceId,
      chunkIndex: w.idx,
      kind: w.kind,
      text: w.text
    }));
  }

  const suggestedFollowupAxes = unique([
    ...allMissingFacets,
    ...(paywalledDomainsOut.length > 0 ? [`paywalled_domains: ${paywalledDomainsOut.join(", ")}`] : []),
    ...(citationGraph.single_primary ? [`single_primary_bottleneck: S${citationGraph.single_primary.primary_source_id}`] : [])
  ]);

  const allClaimsFilteredOut = (ucsRun.gateStats?.rejectedCount || 0) > 0 && dataLayerOut.claims.length === 0;
  const completionState = allClaimsFilteredOut || transportState === "degraded" || diagnostics.incomplete_generations > 0
    ? "degraded"
    : allMissingFacets.length > 0
      ? "partial"
      : "healthy";

  const finalEnvelope = {
    completion_state: completionState,
    transport_state: transportState,
    need_class: routePlan.need_class,
    breadth_mode: routePlan.breadth_mode,
    exactness_mode: routePlan.exactness_mode,
    retrieval_state: {
      search_mode: routePlan.search_mode,
      sift_scale_note: SIFT_SCALE_NOTE,
      branch_statuses: branchStatuses,
      missing_axes: unique(branchMissingAxes),
      branch_errors: failedRuns.map((r) => ({ branch: r.branch, engine: r.engine, error: r.error })),
      hydrated_documents_count: cleanSourcesForOutput.filter((s) => s.is_hydrated).length,
      hop2_verification: hop2Telemetry,
      suggested_followup_axes: suggestedFollowupAxes,
      pipeline_diagnostics: { ...diagnostics, elapsed_ms: elapsedMs() }
    },
    control_layer: {
      epistemic_tension: Boolean(finalPayload.epistemic_tension),
      confidence_ceiling: allClaimsFilteredOut ? "Low" : finalPayload.confidence_ceiling,
      reconciliation_notes: finalPayload.reconciliation_notes || "",
      paywalled_domains: paywalledDomainsOut,
      citation_graph_warnings: {
        circular_chains: citationGraph.circular_chains,
        single_primary: citationGraph.single_primary
      }
    },
    data_layer: dataLayerOut
  };

  return await enforceParentOutputCap(finalEnvelope, evidenceLattice);
}
